import { PrismaClient, Prisma } from '@prisma/client';
import { AsyncLocalStorage } from 'async_hooks';

export const queryMetricsStorage = new AsyncLocalStorage<any>();

// Global singleton to prevent connection exhaustion in dev
const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

/**
 * Environment-aware Prisma log levels.
 * - Production: only 'error' and 'warn' — never log raw SQL.
 * - Development: 'error' + 'warn', plus 'query' when PRISMA_QUERY_LOGGING=true.
 */
function getPrismaLogLevels(): Prisma.LogLevel[] {
  const levels: Prisma.LogLevel[] = ['error', 'warn'];
  if (process.env.NODE_ENV !== 'production' && process.env.PRISMA_QUERY_LOGGING === 'true') {
    levels.push('query');
  }
  return levels;
}

export const basePrisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    log: getPrismaLogLevels(),
  });

/**
 * Helper: retry a Prisma query on transient connection errors
 * (e.g. "Server has closed the connection" from Render PostgreSQL).
 */
const RETRYABLE_ERRORS = [
  'Server has closed the connection',
  'Connection reset by peer',
  'Can\'t reach database server',
  'ECONNRESET',
  'ETIMEDOUT',
  'Connection timed out',
];

function isRetryableError(error: unknown): boolean {
  if (error instanceof Error) {
    return RETRYABLE_ERRORS.some(msg => error.message.includes(msg));
  }
  return false;
}

async function withRetry<T>(fn: () => Promise<T>, maxRetries = 2): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      if (attempt < maxRetries && isRetryableError(error)) {
        console.warn(`[Prisma Retry] Retryable error on attempt ${attempt + 1}/${maxRetries + 1}, reconnecting...`);
        try {
          await basePrisma.$disconnect();
          await basePrisma.$connect();
        } catch {
          // Ignore reconnect errors, the next query attempt will try again
        }
        // Small backoff: 100ms, then 300ms
        await new Promise(r => setTimeout(r, (attempt + 1) * 200));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

export const prisma = basePrisma.$extends({
  query: {
    $allModels: {
      async $allOperations({ model, operation, args, query }) {
        const startTime = Date.now();
        const result = await withRetry(() => query(args));
        const executionTime = Date.now() - startTime;
        
        if (executionTime > 200) {
            console.warn(`[Prisma Profiler - SLOW QUERY (GLOBAL)] Model: ${model}, Operation: ${operation}, Time: ${executionTime}ms`);
        } else if (process.env.PRISMA_PROFILER_LOG === 'true') {
            console.log(`[Prisma Profiler (GLOBAL)] Model: ${model}, Operation: ${operation}, Time: ${executionTime}ms`);
        }

        const perfData = queryMetricsStorage.getStore();
        if (perfData) {
            perfData.numberOfQueries = (perfData.numberOfQueries || 0) + 1;
            perfData.databaseDuration = (perfData.databaseDuration || 0) + executionTime;
            if (!perfData.slowestQuery || executionTime > perfData.slowestQuery.ms) {
                perfData.slowestQuery = { ms: executionTime, query: `GLOBAL:${model}.${operation}` };
            }
        }
        return result;
      }
    }
  }
}) as unknown as PrismaClient;

if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = basePrisma;

/**
 * Returns the central Prisma Client instance.
 * Multi-tenant DB logic has been deprecated and removed.
 */
export const getTenantPrisma = (
  _companyId?: string,
  _onSearchSync?: (model: string, operation: string, result: any, args: any) => void
) => {
  return prisma;
};

export const getTenantDb = async (_tenantId?: string) => {
  return prisma;
};

export const getTenantConnection = (_tenantId?: string) => {
  return prisma;
};


